#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    getline(cin, s);
    vector<char> s_arr(s.begin(), s.end());

    bool x = false;
    int n = s_arr.size();
    for (int i = 0; i < n; i++) {
        x |= (s_arr[i] == 'X');
    }

    int ans = 0;
    vector<char> s2(n);
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < n; j++) {
            if (s_arr[j] == 'X') s2[j] = '0' + i;
            else s2[j] = s_arr[j];
        }
        if (s2[0] == '0') continue; // not possible

        int dp[2][25];
        memset(dp, 0, sizeof(dp));
        int cur = 1;
        dp[0][0] = 1;

        for (int j = 0; j < n; j++) {
            for (int k = 0; k < 25; k++) {
                dp[cur][k] = 0;
            }
            int lo = 0, hi = 9, nxt;
            if (s2[j] != '_') {
                lo = hi = s2[j] - '0';
            } else if (s2[j] == '_' && j == 0) {
                lo++;
            }

            for (int k = 0; k < 25; k++) {
                for (int l = lo; l <= hi; l++) {
                    nxt = (k * 10 + l) % 25;
                    dp[cur][nxt] += dp[cur ^ 1][k];
                }
            }
            cur ^= 1;
        }

        ans += dp[cur ^ 1][0];
        if (!x) break;
    }

    if (n == 1 && (s_arr[0] == '_' || s_arr[0] == 'X' || s_arr[0] == '0')) ans++;
    cout << ans << "\n";

    return 0;
}
